edits.new:
for mode,label in ((1,"unchanged-small-P16"),(2,"unchanged-small-P17")):
    ns["add"](label,mode,valid,accept=(mode==1))
    expected=ns["PLAN"][-1]["expected"]
    classification={"scope":"ACTUAL_ACCEPTED_CORE_REGRESSION",
        "original_public_success_required_before_native":True}
    if mode==2:
        message=("E_HIA_ASSEMBLY_PROFILE: render requires explicit primitive "
                 "v6/v7/v8 Core; use the existing adapter first")
        # Keep this original composite-v1 input. Its admitted Core is
        # primitive-v1; the original public renderer rejects that profile.
        try:ns["render_assembly"](ns["PLAN"][-1]["source"])
        except ns["HIAAssemblyRejected"] as exc:
            assert type(exc) is ns["HIAAssemblyRejected"]
            assert exc.code=="E_HIA_ASSEMBLY_PROFILE" and exc.phase=="representation"
            assert str(exc)==message
        else:raise AssertionError("original render unexpectedly accepted primitive-v1")
        assert {key:expected[key] for key in ("kind","domain","phase","line","code","program")}=={
            "kind":4,"domain":2,"phase":3,"line":0,
            "code":"E_HIA_ASSEMBLY_PROFILE","program":None}
        assert expected["payload"]==message.encode("utf-8")
        classification={"scope":"ACTUAL_ORIGINAL_PUBLIC_RENDER_PROFILE_REFUSAL",
            "original_public_exception_class":"HIAAssemblyRejected",
            "original_public_phase":"representation","original_public_full_text":message,
            "original_public_success_required_before_native":False}
    evidence.append(dict(label=label,source=ns["cas"](ns["PLAN"][-1]["source"]),
                         **classification))
